-- Generated by scripts/generate-meal-seed.mjs from meal-catalogue.json.
-- Requires the meal checkout capability migration. Does not alter that capability.
-- Only INSERTs products/offers; preserves every existing row and customer record.
begin isolation level repeatable read;
set local lock_timeout = '5s';
set local statement_timeout = '300s';
select pg_advisory_xact_lock(hashtextextended('flyora-meal-catalogue-v1', 0));

create or replace function pg_temp.meal_id(label text) returns uuid language sql immutable as $$
  select md5('flyora-meal-catalogue-v1:' || label)::uuid
$$;

-- Include inventory, fares, all customer tables and private roles/payment state.
-- Only the two authorized INSERT targets are checked separately below.
create or replace function pg_temp.meal_protected_fingerprint() returns jsonb language plpgsql as $$
declare r record; digest text; result jsonb := '{}';
begin
  for r in select n.nspname, c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where c.relkind in ('r','p') and (n.nspname='private' or
      (n.nspname='public' and c.relname not in ('addon_products','flight_addon_offers'))) order by 1,2
  loop
    execute format('select md5(coalesce(string_agg(h, '''' order by h),'''')) from (select md5(to_jsonb(t)::text) h from %I.%I t) x', r.nspname, r.relname) into digest;
    result := result || jsonb_build_object(r.nspname || '.' || r.relname, digest);
  end loop;
  return result;
end $$;
create temp table meal_guard on commit drop as select pg_temp.meal_protected_fingerprint() as fingerprint;
create temp table meal_existing_products on commit drop as select id, to_jsonb(p) as snapshot from public.addon_products p;
create temp table meal_existing_offers on commit drop as select id, to_jsonb(o) as snapshot from public.flight_addon_offers o;
create temp table meal_menu on commit drop as
  select m.* from jsonb_to_recordset('[{"code":"MEAL_CHICKEN_RICE","nameVi":"Cơm gà sốt gừng","nameEn":"Ginger chicken rice","descriptionVi":"Cơm trắng, thịt gà sốt gừng và rau củ. Có đậu nành và lúa mì; có thể có dấu vết trứng, sữa, đậu phộng và hải sản.","descriptionEn":"Steamed rice, ginger chicken and vegetables. Contains soy and wheat; may contain traces of egg, milk, peanuts and seafood.","unitAmount":110000},{"code":"MEAL_BEEF_RICE","nameVi":"Cơm bò sốt tiêu","nameEn":"Pepper beef rice","descriptionVi":"Cơm trắng, thịt bò sốt tiêu đen và rau củ. Có đậu nành và lúa mì; có thể có dấu vết trứng, sữa, đậu phộng và hải sản.","descriptionEn":"Steamed rice, black pepper beef and vegetables. Contains soy and wheat; may contain traces of egg, milk, peanuts and seafood.","unitAmount":130000},{"code":"MEAL_TOFU_RICE","nameVi":"Cơm đậu hũ rau củ","nameEn":"Tofu and vegetable rice","descriptionVi":"Cơm, đậu hũ và rau củ sốt nấm, phù hợp chế độ ăn chay. Có đậu nành và lúa mì; có thể có dấu vết trứng, sữa, đậu phộng và hải sản. Không bảo đảm không nhiễm chéo.","descriptionEn":"Rice, tofu and vegetables in mushroom sauce, suitable for a vegetarian diet. Contains soy and wheat; may contain traces of egg, milk, peanuts and seafood. Cross-contact cannot be excluded.","unitAmount":95000},{"code":"MEAL_CHICKEN_SANDWICH","nameVi":"Bánh mì kẹp gà","nameEn":"Chicken sandwich","descriptionVi":"Bánh mì mềm kẹp thịt gà, rau và sốt mayonnaise. Có lúa mì, trứng và sữa; có thể có dấu vết đậu nành, đậu phộng và hải sản.","descriptionEn":"Soft bread with chicken, vegetables and mayonnaise. Contains wheat, egg and milk; may contain traces of soy, peanuts and seafood.","unitAmount":85000},{"code":"MEAL_VEGETABLE_PASTA","nameVi":"Mì Ý sốt cà chua rau củ","nameEn":"Vegetable tomato pasta","descriptionVi":"Mì Ý, rau củ và sốt cà chua, phù hợp chế độ ăn chay. Có lúa mì và trứng; có thể có dấu vết sữa, đậu nành, đậu phộng và hải sản. Không bảo đảm không nhiễm chéo.","descriptionEn":"Pasta with vegetables and tomato sauce, suitable for a vegetarian diet. Contains wheat and egg; may contain traces of milk, soy, peanuts and seafood. Cross-contact cannot be excluded.","unitAmount":105000},{"code":"MEAL_FRUIT_YOGURT","nameVi":"Trái cây và sữa chua","nameEn":"Fruit and yogurt","descriptionVi":"Trái cây theo mùa và một phần sữa chua. Có sữa; có thể có dấu vết trứng, lúa mì, đậu nành và đậu phộng.","descriptionEn":"Seasonal fruit with a serving of yogurt. Contains milk; may contain traces of egg, wheat, soy and peanuts.","unitAmount":75000}]'::jsonb)
    as m(code text, "nameVi" text, "nameEn" text, "descriptionVi" text, "descriptionEn" text, "unitAmount" bigint);
create temp table meal_eligible_flights on commit drop as
  select id from public.flight_instances
  where published_at is not null and status in ('scheduled','delayed')
    and departure_at > now() and sales_close_at > now();
create temp table meal_seed_runs(run integer, result jsonb) on commit drop;

create or replace function pg_temp.populate_meal_catalogue() returns jsonb language plpgsql as $$
declare inserted_products integer; inserted_offers integer;
begin
  insert into public.addon_products(id, code, name, category, description, weight_kg, is_active)
    select pg_temp.meal_id('product:' || code), code, "nameVi", 'meal', "descriptionVi", null, true from meal_menu
    on conflict do nothing;
  get diagnostics inserted_products = row_count;

  -- Fail on identity/category collisions, but respect later admin names or deactivation.
  if exists(select 1 from meal_menu m left join public.addon_products p
      on p.id=pg_temp.meal_id('product:' || m.code) and p.code=m.code
      where p.id is null or p.category<>'meal' or p.weight_kg is not null) then
    raise exception 'Meal product identity/category conflicts; no existing data was overwritten';
  end if;

  insert into public.flight_addon_offers(id, flight_id, product_id, unit_amount, currency, max_quantity_per_passenger, is_active)
    select pg_temp.meal_id('offer:' || f.id || ':' || m.code), f.id, p.id, m."unitAmount", 'VND', 1, true
    from meal_eligible_flights f cross join meal_menu m
    join public.addon_products p on p.code=m.code and p.id=pg_temp.meal_id('product:' || m.code) and p.is_active
    on conflict do nothing;
  get diagnostics inserted_offers = row_count;

  -- Disabled/custom-priced existing offers are retained rather than reopened/reset.
  if exists(select 1 from meal_eligible_flights f cross join meal_menu m
    join public.addon_products p on p.code=m.code and p.is_active
    where not exists(select 1 from public.flight_addon_offers o where o.flight_id=f.id and o.product_id=p.id)) then
    raise exception 'An eligible flight is missing a meal offer';
  end if;
  return jsonb_build_object('inserted_products', inserted_products, 'inserted_offers', inserted_offers);
end $$;

do $$
declare i integer; run_result jsonb;
begin
  for i in 1..1 loop
    run_result := pg_temp.populate_meal_catalogue();
    insert into meal_seed_runs values(i, run_result);
    if i>1 and (run_result->>'inserted_products')::integer + (run_result->>'inserted_offers')::integer <> 0 then
      raise exception 'Repeat inserted duplicate meals/offers';
    end if;
  end loop;

  if exists(select 1 from meal_existing_products old left join public.addon_products p on p.id=old.id
      where p.id is null or to_jsonb(p) is distinct from old.snapshot) or
     exists(select 1 from meal_existing_offers old left join public.flight_addon_offers o on o.id=old.id
      where o.id is null or to_jsonb(o) is distinct from old.snapshot) then
    raise exception 'Existing products/offers changed; rolling back';
  end if;
  if exists(select 1 from public.addon_products p
      where not exists(select 1 from meal_existing_products old where old.id=p.id)
      and not exists(select 1 from meal_menu m where p.id=pg_temp.meal_id('product:' || m.code)
        and p.code=m.code and p.name=m."nameVi" and p.description=m."descriptionVi"
        and p.category='meal' and p.weight_kg is null and p.is_active)) or
     exists(select 1 from public.flight_addon_offers o
      where not exists(select 1 from meal_existing_offers old where old.id=o.id)
      and not exists(select 1 from meal_menu m join public.addon_products p on p.code=m.code
        join meal_eligible_flights f on f.id=o.flight_id
        where o.id=pg_temp.meal_id('offer:' || f.id || ':' || m.code) and o.product_id=p.id
          and o.unit_amount=m."unitAmount" and o.currency='VND' and o.max_quantity_per_passenger=1 and o.is_active)) then
    raise exception 'Unexpected catalogue inserts; rolling back';
  end if;
  if pg_temp.meal_protected_fingerprint() <> (select fingerprint from meal_guard) then
    raise exception 'Protected application or inventory data changed; rolling back';
  end if;
end $$;

select jsonb_build_object('protected_data_unchanged', true, 'existing_products_offers_unchanged', true,
  'eligible_flights', (select count(*) from meal_eligible_flights), 'menu_products', (select count(*) from meal_menu),
  'active_menu_products', (select count(*) from public.addon_products p join meal_menu m on m.code=p.code where p.is_active),
  'menu_offers_on_eligible_flights', (select count(*) from public.flight_addon_offers o
    join meal_eligible_flights f on f.id=o.flight_id join public.addon_products p on p.id=o.product_id
    join meal_menu m on m.code=p.code),
  'runs', (select jsonb_agg(jsonb_build_object('run', run) || result order by run) from meal_seed_runs)) as meal_catalogue_result;
commit;
